var VMSG={email:'อีเมลยังไม่ครบ ลองเช็กว่ามี @ และโดเมน เช่น name@gmail.com ถ้าไม่อยากใส่ ลบออกให้ว่างได้',url:'ลิงก์ยังไม่ครบ เช่น linkedin.com/in/ชื่อ (ไม่ต้องพิมพ์ https://)',year:'ใส่ปี 4 หลัก เช่น 2024 หรือ 2567 (พ.ศ. ระบบแปลงให้เอง)'};
