    if(t==='B'||t==='STRONG'||(t==='SPAN'&&/bold|[6-9]00/.test(st.fontWeight)))c=wrap('**',c,'**');if(t==='I'||t==='EM'||(t==='SPAN'&&st.fontStyle==='italic'))c=wrap('*',c,'*');if(t==='U'||(t==='SPAN'&&/underline/.test(st.textDecoration||'')))c=wrap('++',c,'++');if(t==='MARK')c=wrap('==',c,'==');
