  var lab=document.querySelector('label[for="'+ta.id+'"]');if(lab){if(!lab.id)lab.id=ta.id+'L';ed.setAttribute('aria-labelledby',lab.id)}ed.style.minHeight=Math.max(88,(+ta.rows||3)*26+20)+'px';ed.innerHTML=rtHtml(ta.value);
