function tplOf(c){var t=(c.chapters||[]).map(function(x){return x.t}).join('|');for(var i=0;i<TPL.length;i++)if(TPL[i][3].map(function(x){return x[0]}).join('|')===t)return TPL[i];return null}
function tplName(c){var t=tplOf(c);return t?'โครง '+t[1]:'จัดเอง'}
function tplChapters(id){var t=TPL.filter(function(x){return x[0]===id})[0];return t[3].map(function(ch){return{t:ch[0],b:ch[1].map(function(bt,i){return newBlk(bt,i===0?ch[2]:'')})}})}
function tplRec(k){var c=D.cases[k]||{},w=mainOf(k),q=[c.cat,c.role,(c.scope||[]).join(' '),w&&w.cat,D.profile.role].join(' ').toLowerCase(),r=[];
  if(/research|วิจัย/.test(q))r.push('research');if(/front|dev|engineer|code|โค้ด/.test(q))r.push('dev');if(/design system/.test(q))r.push('ds');if(/brand|graphic|visual/.test(q))r.push('brand','ui');if(/\bai\b|prompt/.test(q))r.push('aiw');if(/ux|ui|product|mobile|web|app/.test(q))r.push('ux','dt');
  r=r.filter(function(x,i){return r.indexOf(x)===i});return r.length?r.slice(0,3):['ux','basic']}
function isPristine(c){return (c.chapters||[]).every(function(ch){return (ch.b||[]).every(blkEmpty)})}
function tplWire(t){return '<p class="pv-t">'+esc(t[1])+'</p><p class="pv-d">'+esc(t[4])+'</p><ol class="pv-ch">'+t[3].map(function(ch,i){return '<li><span class="pv-n">'+(i+1)+'</span><span class="pv-b"><b>'+esc(ch[0])+'</b>'+ch[1].map(wf).join('')+'</span></li>'}).join('')+'</ol>'}
